"use client";
import { useState } from "react";
import { EOS_GRADIENT_NAMES, EOS_LOOK_SPECS, eosLook, type EosLook, type EosMode } from "@/components/application/eos/tokens";
import { EOS_LOOK_SEGMENTS } from "@/components/application/eos/design-page";
import { EosGradientBanner } from "@/components/application/eos/gradient-banner";
import { EosPillFilters } from "@/components/application/eos/pill-filters";
import { EosSegmentedControl } from "@/components/application/eos/segmented-control";
import { EosTheme } from "@/components/application/eos/theme";

const NAMES = { dawn: "Dawn", blush: "Blush", lagoon: "Lagoon", orchid: "Orchid", citrine: "Citrine" } as const;

/** One look's tokens in one mode: the display face over the grey sans, the five grain gradients with their ink, and pills. */
function Sheet({ mode, look }: { mode: EosMode; look: EosLook }) {
  return (
    <EosTheme mode={mode} look={look} style={{ padding: "28px 24px", borderRadius: "var(--eos-radius-card)", border: "1px solid var(--eos-hairline)" }}>
      <p
        style={{
          margin: 0,
          fontFamily: "var(--eos-font-display)",
          fontWeight: "var(--eos-display-weight)",
          fontSize: 34,
          lineHeight: 1.05,
          letterSpacing: "var(--eos-display-tracking)",
          color: "var(--eos-page-text)",
        }}
      >
        Routines that run while you sleep
      </p>
      <p style={{ margin: "10px 0 22px", fontSize: 15.5, color: "var(--eos-page-text-soft)" }}>
        {EOS_LOOK_SPECS[look].title}, {mode}
      </p>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(64px, 1fr))", gap: 10 }}>
        {EOS_GRADIENT_NAMES.map((name, i) => (
          <div key={name} style={{ display: "grid", gap: 8, minWidth: 0 }}>
            {/* Each gradient carries a sample of the ink set on it. */}
            <EosGradientBanner gradient={name} shape="card" height={96} flip={i % 2 === 1} aria-hidden>
              <span style={{ fontFamily: "var(--eos-font-display)", fontSize: 24, lineHeight: 1, color: `var(--eos-ink-${name})` }}>Aa</span>
            </EosGradientBanner>
            <span style={{ fontSize: 13, color: "var(--eos-page-text-soft)" }}>{NAMES[name]}</span>
          </div>
        ))}
      </div>
      <EosPillFilters
        size="md"
        label={`${mode} pills`}
        items={[
          { value: "all", label: "All" },
          { value: "finance", label: "Finance" },
          { value: "sales", label: "Sales" },
        ]}
        style={{ marginTop: 20 }}
      />
    </EosTheme>
  );
}

/** The Eos tokens in each of the five looks, light and dark side by side. */
export default function EosThemeDemo() {
  const [look, setLook] = useState<EosLook>("pastel");
  return (
    <div style={{ display: "grid", gap: 16, width: "100%", maxWidth: 980, margin: "0 auto" }}>
      <EosSegmentedControl segments={EOS_LOOK_SEGMENTS} value={look} onChange={(value) => setLook(eosLook(value))} label="Look" size="sm" style={{ justifySelf: "center" }} />
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(min(100%, 380px), 1fr))", gap: 16 }}>
        <Sheet mode="light" look={look} />
        <Sheet mode="dark" look={look} />
      </div>
    </div>
  );
}

