/**
 * Eos, the theme of the dawn, as plain data: the single source of truth for its light and dark values, its five
 * looks, the gradient sets and the type. EosTheme (theme.tsx) writes these onto its own wrapper, and the tests read
 * them directly.
 *
 * Inspired by rico (@_heyrico)'s twin visual vibe.
 *
 * A warm off-white page with white hairline cards and big radii, grainy pastel gradients holding app tiles, black
 * pills, a serif display over a grey sans body, and a charcoal app shell for dark mode. Inside an Eos scope the
 * Zeus semantic tokens (--color-text-*, --color-background-*, --color-border-*, --font-sans) take Eos values, so any
 * Zeus component placed there takes the theme too. Nothing is injected globally.
 *
 * One theme, five looks: pastel, night, editorial, glass and bold. The looks share the base values and override only
 * where they differ (surfaces, gradients, the type pairing, radii and density), plus a few layout choices
 * (EosLookLayout) that the design page and the market card read. Light and dark are a separate axis: every look has
 * both.
 *
 * Fonts are free and named with fallbacks; load them yourself: Newsreader (display), Inter (body) and, for the bold
 * look, Bricolage Grotesque.
 */

export const EOS_MODES = ["light", "dark"] as const;
export type EosMode = (typeof EOS_MODES)[number];

export const EOS_LOOKS = ["pastel", "night", "editorial", "glass", "bold"] as const;
export type EosLook = (typeof EOS_LOOKS)[number];

/** A look by name; anything else falls back to pastel, the look as first drawn. */
export function eosLook(value: unknown): EosLook {
  return EOS_LOOKS.find((look) => look === value) ?? "pastel";
}

export const EOS_GRADIENT_NAMES = ["dawn", "blush", "lagoon", "orchid", "citrine"] as const;
export type EosGradientName = (typeof EOS_GRADIENT_NAMES)[number];

/** Each family with its fallbacks. Consumers load the fonts themselves. */
export const EOS_FONTS = {
  display: '"Newsreader", "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif',
  body: '"Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif',
  grotesk: '"Bricolage Grotesque", "Inter", ui-sans-serif, system-ui, sans-serif',
  mono: '"JetBrains Mono", ui-monospace, "SFMono-Regular", Menlo, monospace',
} as const;

/** Every colour Eos names. Translucent values are composited over what they sit on before any contrast check. */
export interface EosColors {
  /** The page. */
  canvas: string;
  card: string;
  /** A card inside a card, such as the about card. */
  inner: string;
  /** A pale fill: specimen frames, quiet wells. */
  well: string;
  /** The app shell's main area. */
  shell: string;
  sidebar: string;
  /** The active row in the shell's nav. */
  navActive: string;
  /** The segmented control's track and its chosen segment. */
  segTrack: string;
  segActive: string;
  /** A hover wash, laid over whatever is below. */
  hover: string;
  hairline: string;
  hairlineStrong: string;
  text: string;
  textSecondary: string;
  textTertiary: string;
  pill: string;
  pillText: string;
  pillBorder: string;
  pillActive: string;
  pillActiveText: string;
  /** Unread dots and small signals. */
  accent: string;
  focus: string;
  /** The solid app tile. */
  tile: string;
  tileRim: string;
  /** The frosted tile: translucent fill, light rim, top highlight and the glyph it holds. */
  frost: string;
  frostRim: string;
  frostHighlight: string;
  frostGlyph: string;
  /** Behind a drawer. */
  scrim: string;
  /** The page's top bar, over whatever scrolls under it. */
  bar: string;
}

/** Radii, type, effects and density. Lengths are px unless the value is a string. */
export interface EosShape {
  cardRadius: number;
  /** The banner inside a card: the card radius less its inset, so the corners stay concentric. */
  bannerRadius: number;
  bannerInset: number;
  tileRadius: number;
  innerRadius: number;
  pillRadius: number;
  displayFont: string;
  bodyFont: string;
  /** Detail and hero headlines. */
  displaySize: number;
  /** Section titles, such as Discover. */
  headingSize: number;
  displayWeight: number;
  displayTracking: string;
  /** Grain strength over gradients, 0 to 1. */
  grain: number;
  frostBlur: number;
  /** Blur behind cards; 0 keeps them solid. */
  cardBlur: number;
  tileShadow: string;
  cardShadow: string;
  floatShadow: string;
  /** Density: the widest the page's content runs, the space between its sections and between cards, and the narrowest a card gets. */
  pageWidth: number;
  sectionGap: number;
  gridGap: number;
  cardMin: number;
}

/** A grain gradient: stops from start to end along `angle`, a soft glow laid over it, and the text it can carry. */
export interface EosGradient {
  stops: readonly string[];
  angle: number;
  /** Petals and bloom: translucent light over the stops. */
  glow: string;
  /** Text on the field, and its quieter line. */
  ink: string;
  inkSoft: string;
}
export type EosGradientSet = Readonly<Record<EosGradientName, EosGradient>>;

const darkInk = { ink: "#22211F", inkSoft: "#33322F" } as const;
const lightInk = { ink: "#FFFFFF", inkSoft: "#F4F4F6" } as const;
const glassInk = { ink: "#1F1E1C", inkSoft: "#2B2A27" } as const;

/** Five tones of the same five gradients. Each look picks one per mode. */
export const EOS_GRADIENT_SETS = {
  /** rico's soft grain pastels. */
  pastel: {
    dawn: { stops: ["#A48CF0", "#B5C6F8", "#82C8F4"], angle: 115, glow: "rgba(255, 255, 255, 0.42)", ...darkInk },
    blush: { stops: ["#F29BCB", "#F6A58B", "#F6C36C"], angle: 120, glow: "rgba(255, 246, 240, 0.40)", ...darkInk },
    lagoon: { stops: ["#2AB4AE", "#7ED7D3", "#9BD6F0"], angle: 125, glow: "rgba(240, 255, 252, 0.36)", ...darkInk },
    orchid: { stops: ["#BBA0F2", "#E8A5D6", "#F5C1D9"], angle: 120, glow: "rgba(255, 255, 255, 0.40)", ...darkInk },
    citrine: { stops: ["#F5DF96", "#F6BC88", "#F3A898"], angle: 120, glow: "rgba(255, 255, 245, 0.42)", ...darkInk },
  },
  /** Deeper and dimmer, for dark mode. */
  deep: {
    dawn: { stops: ["#2E2563", "#253A78", "#1A4E72"], angle: 115, glow: "rgba(150, 170, 255, 0.12)", ...lightInk },
    blush: { stops: ["#5A1E46", "#6B2B33", "#64401A"], angle: 120, glow: "rgba(255, 180, 160, 0.10)", ...lightInk },
    lagoon: { stops: ["#0D4846", "#125A58", "#174C62"], angle: 125, glow: "rgba(160, 255, 240, 0.10)", ...lightInk },
    orchid: { stops: ["#3B2466", "#5A2251", "#5A2A44"], angle: 120, glow: "rgba(230, 180, 255, 0.10)", ...lightInk },
    citrine: { stops: ["#54451A", "#633C1E", "#5A2E2A"], angle: 120, glow: "rgba(255, 230, 170, 0.10)", ...lightInk },
  },
  /** Lower chroma, for thin bands and swatches. */
  quiet: {
    dawn: { stops: ["#CFC6F2", "#D3DDF6", "#C6E2F4"], angle: 115, glow: "rgba(255, 255, 255, 0.35)", ...darkInk },
    blush: { stops: ["#F3CDE0", "#F5D0C4", "#F4E0B9"], angle: 120, glow: "rgba(255, 255, 255, 0.35)", ...darkInk },
    lagoon: { stops: ["#B3E0DB", "#CDEDEA", "#D2E9F4"], angle: 125, glow: "rgba(255, 255, 255, 0.35)", ...darkInk },
    orchid: { stops: ["#DCCFF3", "#F0D3E5", "#F6E0EA"], angle: 120, glow: "rgba(255, 255, 255, 0.35)", ...darkInk },
    citrine: { stops: ["#F4EBC4", "#F4D8BE", "#F2CFC8"], angle: 120, glow: "rgba(255, 255, 255, 0.35)", ...darkInk },
  },
  /** Brighter and wider, for full-bleed glass. */
  luminous: {
    dawn: { stops: ["#9A83F2", "#A9C1FA", "#86D2F8"], angle: 115, glow: "rgba(255, 255, 255, 0.50)", ...glassInk },
    blush: { stops: ["#F49ACB", "#FAAE98", "#FBD27F"], angle: 120, glow: "rgba(255, 250, 245, 0.48)", ...glassInk },
    lagoon: { stops: ["#36C0BA", "#93E5DF", "#8CCFF5"], angle: 125, glow: "rgba(245, 255, 252, 0.45)", ...glassInk },
    orchid: { stops: ["#B096F4", "#EFA4D6", "#F8C7DE"], angle: 120, glow: "rgba(255, 255, 255, 0.48)", ...glassInk },
    citrine: { stops: ["#FAE59E", "#F9BC8F", "#F5A5B3"], angle: 120, glow: "rgba(255, 255, 248, 0.50)", ...glassInk },
  },
  /** Saturated, for the bold bento. */
  vivid: {
    dawn: { stops: ["#6B2BE2", "#3D45F2", "#1F5BFF"], angle: 125, glow: "rgba(140, 120, 255, 0.14)", ink: "#FFFFFF", inkSoft: "#F7F8FF" },
    blush: { stops: ["#FF2E7E", "#FF5A4F", "#FF8A1F"], angle: 120, glow: "rgba(255, 220, 180, 0.18)", ink: "#1A0C12", inkSoft: "#2B141B" },
    lagoon: { stops: ["#00A896", "#26CC7C", "#B5EE3A"], angle: 120, glow: "rgba(230, 255, 200, 0.18)", ink: "#0B1A14", inkSoft: "#14271E" },
    orchid: { stops: ["#7429F0", "#A324D0", "#BF2390"], angle: 125, glow: "rgba(255, 190, 240, 0.08)", ink: "#FFFFFF", inkSoft: "#FBF6FF" },
    citrine: { stops: ["#FFD60A", "#FFB01F", "#FF8C2E"], angle: 120, glow: "rgba(255, 255, 230, 0.28)", ink: "#1F1606", inkSoft: "#33240B" },
  },
} as const satisfies Record<string, EosGradientSet>;
export type EosGradientTone = keyof typeof EOS_GRADIENT_SETS;

export const EOS_LIGHT: EosColors = {
  canvas: "#F7F6F4",
  card: "#FFFFFF",
  inner: "#FFFFFF",
  well: "#F2F1EE",
  shell: "#FBFAF8",
  sidebar: "#F3F2EF",
  navActive: "#E8E7E3",
  segTrack: "#ECEBE7",
  segActive: "#FFFFFF",
  hover: "rgba(28, 27, 25, 0.04)",
  hairline: "rgba(28, 27, 25, 0.08)",
  hairlineStrong: "rgba(28, 27, 25, 0.14)",
  text: "#2A2927",
  textSecondary: "#62615D",
  textTertiary: "#6A6964",
  pill: "#FFFFFF",
  pillText: "#2A2927",
  pillBorder: "rgba(28, 27, 25, 0.12)",
  pillActive: "#1E1E1D",
  pillActiveText: "#FFFFFF",
  accent: "#3B82F6",
  focus: "#2563EB",
  tile: "#FFFFFF",
  tileRim: "rgba(28, 27, 25, 0.06)",
  frost: "rgba(255, 255, 255, 0.24)",
  frostRim: "rgba(255, 255, 255, 0.55)",
  frostHighlight: "rgba(255, 255, 255, 0.65)",
  frostGlyph: "#FFFFFF",
  scrim: "rgba(20, 19, 18, 0.32)",
  bar: "rgba(247, 246, 244, 0.84)",
};

export const EOS_DARK: EosColors = {
  canvas: "#161616",
  card: "#1F1F1F",
  inner: "#232323",
  well: "#1C1C1C",
  shell: "#1B1B1B",
  sidebar: "#1E1E1E",
  navActive: "#2A2A2A",
  segTrack: "#262626",
  segActive: "#161616",
  hover: "rgba(255, 255, 255, 0.04)",
  hairline: "#2E2E2E",
  hairlineStrong: "#3A3A3A",
  text: "#EDEDEC",
  textSecondary: "#A3A3A0",
  textTertiary: "#8E8E8A",
  pill: "#1F1F1F",
  pillText: "#EDEDEC",
  pillBorder: "#333333",
  pillActive: "#EDEDEC",
  pillActiveText: "#161616",
  accent: "#5B9BFF",
  focus: "#7AA7FF",
  tile: "#2A2A2A",
  tileRim: "rgba(255, 255, 255, 0.08)",
  frost: "rgba(255, 255, 255, 0.10)",
  frostRim: "rgba(255, 255, 255, 0.22)",
  frostHighlight: "rgba(255, 255, 255, 0.30)",
  frostGlyph: "#FFFFFF",
  scrim: "rgba(0, 0, 0, 0.5)",
  bar: "rgba(22, 22, 22, 0.82)",
};

export const EOS_SHAPE: EosShape = {
  cardRadius: 28,
  bannerRadius: 22,
  bannerInset: 6,
  tileRadius: 20,
  innerRadius: 20,
  pillRadius: 999,
  displayFont: EOS_FONTS.display,
  bodyFont: EOS_FONTS.body,
  displaySize: 46,
  headingSize: 34,
  displayWeight: 420,
  displayTracking: "-0.02em",
  grain: 0.4,
  frostBlur: 14,
  cardBlur: 0,
  tileShadow: "0 1px 2px rgba(28, 27, 25, 0.06), 0 8px 18px -8px rgba(28, 27, 25, 0.20)",
  cardShadow: "0 1px 2px rgba(28, 27, 25, 0.03)",
  floatShadow: "0 30px 70px -30px rgba(28, 27, 25, 0.45), 0 2px 8px rgba(28, 27, 25, 0.08)",
  pageWidth: 1280,
  sectionGap: 128,
  gridGap: 24,
  cardMin: 300,
};

/**
 * The few structural choices a look makes; everything else about it is tokens. The design page reads all of them, the
 * market card reads `cards` and `tiles`, and the detail header reads `detail`. Plain CSS can follow the look through
 * the scope's data-eos-look.
 */
export interface EosLookLayout {
  /** What runs down the side of the page: the A to Z index of categories, the app's own sidebar, or nothing. */
  rail: "index" | "app" | null;
  /** Market cards: app tiles on an inset grain banner, or a big title over a pale frame with a thin band. */
  cards: "banner" | "frame";
  /** The tiles on those cards: white, or frosted glass. */
  tiles: "white" | "frosted";
  /** The Discover grid: even columns, or a bento of wide and narrow tiles. */
  grid: "even" | "bento";
  /** The connect page: a card with a grain banner, a hero on the page's own gradient, Overview and Details tabs, or bento tiles. */
  detail: "card" | "hero" | "tabs" | "bento";
  /** The app on the page: framed on a grain field, in a pale frame, floating as dark glass, as a bento tile, or as the page itself. */
  app: "field" | "frame" | "float" | "tile" | "page";
}

export interface EosLookSpec {
  title: string;
  /** One line on how the look differs. */
  summary: string;
  /** The mode the look is shown in when nothing asks for the other. */
  mode: EosMode;
  /** The gradient tone each mode uses. */
  tone: Readonly<Record<EosMode, EosGradientTone>>;
  /** A gradient laid behind the whole page, if any. */
  backdrop: EosGradientName | null;
  layout: EosLookLayout;
  light?: Partial<EosColors>;
  dark?: Partial<EosColors>;
  shape?: Partial<EosShape>;
  /** Shape changes for one mode only, on top of `shape`. */
  darkShape?: Partial<EosShape>;
}

export const EOS_LOOK_SPECS: Readonly<Record<EosLook, EosLookSpec>> = {
  pastel: {
    title: "Pastel",
    summary: "Soft grain banners on white cards, a frosted connect link, and the dark app framed on a gradient",
    mode: "light",
    tone: { light: "pastel", dark: "deep" },
    backdrop: null,
    layout: { rail: null, cards: "banner", tiles: "white", grid: "even", detail: "card", app: "field" },
  },
  night: {
    title: "Night",
    summary: "The page becomes the dark app: its sidebar runs beside deeper, dimmer gradients and frosted tiles",
    mode: "dark",
    tone: { light: "pastel", dark: "deep" },
    backdrop: null,
    layout: { rail: "app", cards: "banner", tiles: "frosted", grid: "even", detail: "card", app: "page" },
    dark: { canvas: "#1B1B1B", bar: "rgba(27, 27, 27, 0.84)", frost: "rgba(255, 255, 255, 0.12)", frostRim: "rgba(255, 255, 255, 0.24)" },
    shape: { grain: 0.32, pageWidth: 1120, sectionGap: 104, cardMin: 280 },
  },
  editorial: {
    title: "Editorial",
    summary: "A much bigger serif and more air: an A to Z index, wide pale frames, tabs and a quote, gradients cut to thin bands",
    mode: "light",
    tone: { light: "quiet", dark: "deep" },
    backdrop: null,
    layout: { rail: "index", cards: "frame", tiles: "white", grid: "even", detail: "tabs", app: "frame" },
    light: { canvas: "#F7F6F3", well: "#F0EFEB", bar: "rgba(247, 246, 243, 0.86)" },
    shape: {
      displaySize: 92,
      headingSize: 92,
      displayWeight: 380,
      displayTracking: "-0.03em",
      grain: 0.28,
      pageWidth: 1120,
      sectionGap: 168,
      gridGap: 48,
      cardMin: 380,
    },
  },
  glass: {
    title: "Glass",
    summary: "A full-bleed grain gradient under frosted cards and pills, with the connect motif as a large hero",
    mode: "light",
