/** The motion stylesheet, built once. */
export const EOS_MOTION_CSS = eosMotionCss();

/* ------------------------------------------------------------------------------------------------------------------ */
/* The look's cross-fade                                                                                               */
/* ------------------------------------------------------------------------------------------------------------------ */

let switching = 0;
let applying = 0;

/** True while a change of look is being applied: what mounts for the new look then appears with it, without rising. */
export const eosApplyingLook = (): boolean => applying > 0;

/** Whether a piece should rise in as it mounts: on the page's load and later, but not when it mounts for a new look. */
export function useEosEntrance(): boolean {
  return useState(() => !eosApplyingLook())[0];
}

/**
 * Change the look with a cross-fade. Where the browser has view transitions and motion is allowed, `apply` runs inside
 * one: the old picture stays put and the new one fades in over it, on opacity alone. Otherwise `apply` runs at once.
 * `apply` must update the page synchronously. While it runs the page's own transitions are off (`eos-switching` on
 * the root), so the new picture is the finished look rather than one on its way, and the root's two pictures drop any
 * animation, blend or mask the host page gives its own view transitions.
 */
export function eosCrossfade(apply: () => void, look?: EosLook): void {
  const run = () => {
    applying += 1;
    try {
      apply();
    } finally {
      applying -= 1;
    }
  };
  const doc = typeof document === "undefined" ? null : document;
  if (!doc || typeof doc.startViewTransition !== "function" || eosReducedMotion()) {
    run();
    return;
  }
  const root = doc.documentElement;
  const mine = ++switching;
  const motion = eosMotion(look);
  root.classList.add("eos-switching");
  const transition = doc.startViewTransition(run);
  transition.ready
    .then(() => {
      root.animate?.({ opacity: [0, 1] }, { duration: motion.look, easing: eosEaseCss(motion.ease), pseudoElement: "::view-transition-new(root)" });
    })
    .catch(() => {});
  transition.finished
    .catch(() => {})
    .then(() => {
      if (mine === switching) root.classList.remove("eos-switching");
    });
}

/* ------------------------------------------------------------------------------------------------------------------ */
/* Loops                                                                                                               */
/* ------------------------------------------------------------------------------------------------------------------ */

interface LoopState {
  visible: boolean;
}

const loops = new Map<Element, LoopState>();
let loopObserver: IntersectionObserver | null = null;
let loopMedia: MediaQueryList | null = null;

const pageShown = () => typeof document === "undefined" || document.visibilityState !== "hidden";

function writeLoop(el: Element, state: LoopState) {
  el.setAttribute("data-eos-loop", state.visible && pageShown() && !eosReducedMotion() ? "on" : "off");
}

function syncLoops() {
  for (const [el, state] of loops) writeLoop(el, state);
}

/**
 * Run `el`'s loop only while it shows: on screen, in a visible tab, with motion allowed. It sets data-eos-loop to "on"
 * or "off" on the element, and the loop's CSS runs only under "on" (it holds still otherwise, and before any script
 * runs). Returns the function that stops watching.
 */
export function eosWatchLoop(el: Element): () => void {
  const watched = typeof IntersectionObserver === "function";
  const state: LoopState = { visible: !watched };
  loops.set(el, state);
  if (loops.size === 1 && typeof document !== "undefined") {
    document.addEventListener("visibilitychange", syncLoops);
    loopMedia = typeof window.matchMedia === "function" ? window.matchMedia(EOS_REDUCED_MOTION_QUERY) : null;
    loopMedia?.addEventListener?.("change", syncLoops);
  }
  if (watched) {
    loopObserver ??= new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          const seen = loops.get(entry.target);
          if (!seen) continue;
          seen.visible = entry.isIntersecting;
          writeLoop(entry.target, seen);
        }
      },
      { rootMargin: "48px" },
    );
    loopObserver.observe(el);
  }
  writeLoop(el, state);
  return () => {
    loopObserver?.unobserve(el);
    loops.delete(el);
    el.setAttribute("data-eos-loop", "off");
    if (loops.size > 0) return;
    if (typeof document !== "undefined") document.removeEventListener("visibilitychange", syncLoops);
    loopMedia?.removeEventListener?.("change", syncLoops);
    loopMedia = null;
    loopObserver?.disconnect();
    loopObserver = null;
  };
}

/** A component's loop: watched while it is mounted and `enabled`. */
export function useEosLoop(ref: RefObject<Element | null>, enabled = true): void {
  useEffect(() => {
    const el = ref.current;
    if (!el || !enabled) return;
    return eosWatchLoop(el);
  }, [ref, enabled]);
}

/* ------------------------------------------------------------------------------------------------------------------ */
/* The sliding indicator                                                                                               */
/* ------------------------------------------------------------------------------------------------------------------ */

/** A box in px, relative to the indicator's host. */
export interface EosBox {
  x: number;
  y: number;
  w: number;
  h: number;
}

/** The width of an indicator's ends: its corner radius rounded up, and never more than half its width. */
export const eosIndicatorCap = (radius: number, width: number) => Math.max(0, Math.min(Math.ceil(radius), Math.floor(width / 2)));

/**
 * FLIP for an indicator in three parts. The box is already at its final place; it moves there from `from` by the
 * inverse translate, the middle stretches from its left edge by the inverse scaleX, and the right end rides on the
 * inverse of the change in width. The ends never scale, so the rounded corners keep their shape at every frame.
 * `seam` is how far the middle tucks under each end.
 */
export function eosIndicatorFrames(from: EosBox, to: EosBox, cap: number, seam = 0) {
  const middle = (w: number) => Math.max(0, w - 2 * cap + 2 * seam);
  const finalMiddle = middle(to.w);
  const scale = finalMiddle > 0 ? middle(from.w) / finalMiddle : 1;
  const round = (n: number) => Math.round(n * 1000) / 1000;
  return {
    box: [{ transform: `translate(${round(from.x - to.x)}px, ${round(from.y - to.y)}px)` }, { transform: "translate(0px, 0px)" }],
    middle: [{ transform: `scaleX(${round(scale)})` }, { transform: "scaleX(1)" }],
    end: [{ transform: `translateX(${round(from.w - to.w)}px)` }, { transform: "translateX(0px)" }],
  } satisfies Record<string, Keyframe[]>;
}

/** The box an indicator shows `progress` (0 to 1, in time) of the way from `from` to `to`, on the Eos curve. */
export function eosBoxAt(from: EosBox, to: EosBox, progress: number, ease: (t: number) => number = eosEase): EosBox {
  const e = ease(Math.min(1, Math.max(0, progress)));
  const mix = (a: number, b: number) => a + (b - a) * e;
  return { x: mix(from.x, to.x), y: mix(from.y, to.y), w: mix(from.w, to.w), h: mix(from.h, to.h) };
}

/**
 * `el`'s layout box, transforms aside, relative to the padding box of `host`. The host must be positioned and hold
 * `el`; any positioned element between them counts its border.
 */
export function eosBoxWithin(el: HTMLElement, host: HTMLElement): EosBox {
  let x = 0;
  let y = 0;
  for (let node: HTMLElement = el; ; ) {
    x += node.offsetLeft;
    y += node.offsetTop;
    const parent = node.offsetParent as HTMLElement | null;
    if (parent === host) return { x, y, w: el.offsetWidth, h: el.offsetHeight };
    if (!parent || !host.contains(parent)) break;
    x += parent.clientLeft;
    y += parent.clientTop;
    node = parent;
  }
  // The host is not in the chain (not positioned): measure on screen instead.
  const a = el.getBoundingClientRect();
  const b = host.getBoundingClientRect();
  return { x: a.left - b.left - host.clientLeft + host.scrollLeft, y: a.top - b.top - host.clientTop + host.scrollTop, w: el.offsetWidth, h: el.offsetHeight };
}

const sameBox = (a: EosBox | null, b: EosBox) => a !== null && a.x === b.x && a.y === b.y && a.w === b.w && a.h === b.h;

export interface EosIndicatorOptions {
  /** The positioned element that holds both the indicator and the items. */
  host: RefObject<HTMLElement | null>;
  /** The indicator, as EosIndicator renders it. */
  indicator: RefObject<HTMLElement | null>;
  /** The chosen item, or nothing (the indicator then hides). */
  target: () => HTMLElement | null | undefined;
  /** Anything that changes when the choice does. A change slides the indicator; any other move places it at once. */
  choice: unknown;
  /** The indicator's corner radius in px, ring aside. By default the chosen item's own, at most half its height. */
  radius?: number;
  /** A ring drawn just inside the indicator's edge, in px; the indicator grows by it on every side. */
  ring?: number;
  /** An opaque fill: the middle then tucks under the ends, so no seam shows while it stretches. */
  opaque?: boolean;
  look?: EosLook;
}

interface IndicatorRun {
  from: EosBox;
  to: EosBox;
  duration: number;
  animations: Animation[];
}

/**
 * A shared indicator that slides to the chosen item with FLIP: its final box is set once, then the inverse translate
 * and scaleX animate to identity. On the server, and until it is placed, the host has no data-eos-ind="on" and the
 * chosen item paints itself. A new choice mid-slide starts from where the indicator shows; a change of size (a font
 * arriving, a new look) moves it at once. Under reduced motion it jumps.
 */
export function useEosIndicator(options: EosIndicatorOptions): void {
  const latest = useRef(options);
  latest.current = options;
  const placed = useRef<EosBox | null>(null);
  const run = useRef<IndicatorRun | null>(null);
  const mounted = useRef<{ host: HTMLElement; indicator: HTMLElement } | null>(null);

  const stop = () => {
    for (const animation of run.current?.animations ?? []) animation.cancel();
    run.current = null;
  };

  /** Where the indicator shows now: part of the way along mid-slide, its box at rest. */
  const shown = (): EosBox | null => {
    const current = run.current;
    const time = current?.animations[0]?.currentTime;
    if (!current || typeof time !== "number" || current.duration <= 0 || time >= current.duration) return placed.current;
    return eosBoxAt(current.from, current.to, time / current.duration, eosBezier(eosMotion(latest.current.look).ease));
  };

  const place = useCallback((slide: boolean) => {
    const { host, indicator, target, radius, ring = 0, opaque = false, look } = latest.current;
    const root = host.current;
    const ind = indicator.current;
    if (!root || !ind) return;
    // A host that mounted again (a list shown anew) starts fresh, without sliding in from where the old one was.
    if (mounted.current?.host !== root || mounted.current.indicator !== ind) {
      stop();
      placed.current = null;
      mounted.current = { host: root, indicator: ind };
    }
    const item = target();
    if (!item) {
      stop();
      placed.current = null;
      root.setAttribute("data-eos-ind", "off");
      return;
    }
    const raw = eosBoxWithin(item, root);
    // Not laid out (inside display: none): keep what was there.
    if (raw.w === 0 && raw.h === 0) return;
    const box = { x: raw.x - ring, y: raw.y - ring, w: raw.w + 2 * ring, h: raw.h + 2 * ring };
    if (sameBox(placed.current, box) && root.getAttribute("data-eos-ind") === "on") return;
    const from = slide ? shown() : null;
    const own = radius ?? (typeof getComputedStyle === "function" ? parseFloat(getComputedStyle(item).borderTopLeftRadius) || 0 : 0);
    const corner = Math.min(own, raw.h / 2) + ring;
    const cap = eosIndicatorCap(corner, box.w);
    const seam = opaque ? 1 : 0;
    ind.style.left = `${box.x}px`;
    ind.style.top = `${box.y}px`;
    ind.style.width = `${box.w}px`;
    ind.style.height = `${box.h}px`;
    ind.style.setProperty("--eos-ind-cap", `${cap}px`);
    ind.style.setProperty("--eos-ind-radius", `${corner}px`);
    ind.style.setProperty("--eos-ind-rw", `${ring}px`);
    ind.style.setProperty("--eos-ind-seam", `${seam}px`);
    stop();
    placed.current = box;
    root.setAttribute("data-eos-ind", "on");
    const middle = ind.querySelector<HTMLElement>(".eos-ind-m");
    const end = ind.querySelector<HTMLElement>(".eos-ind-r");
    if (!from || sameBox(from, box) || !middle || !end || !eosCanAnimate(ind)) return;
    const motion = eosMotion(look);
    const timing: KeyframeAnimationOptions = { duration: motion.indicator, easing: eosEaseCss(motion.ease) };
    const frames = eosIndicatorFrames(from, box, cap, seam);
    run.current = {
      from,
      to: box,
      duration: motion.indicator,
      animations: [ind.animate(frames.box, timing), middle.animate(frames.middle, timing), end.animate(frames.end, timing)],
    };
  }, []);

  // After every render: a new choice slides; anything else that moved the chosen item (a new look, a list shown
  // anew) places the indicator at once. An unchanged box costs a few reads.
  const lastChoice = useRef<{ value: unknown } | null>(null);
  useIsoLayoutEffect(() => {
    const changed = lastChoice.current !== null && !Object.is(lastChoice.current.value, options.choice);
    lastChoice.current = { value: options.choice };
    place(changed);
  });

  // A change of size without a render (a font arriving, the window resizing) moves it at once.
  const observed = useRef<{ observer: ResizeObserver; host: HTMLElement; item: HTMLElement | null } | null>(null);
  useEffect(() => {
    const root = options.host.current;
    const item = latest.current.target() ?? null;
    const watching = observed.current;
    if (watching && watching.host === root && watching.item === item) return;
    watching?.observer.disconnect();
    observed.current = null;
    if (!root || typeof ResizeObserver !== "function") return;
    const observer = new ResizeObserver(() => place(false));
    observer.observe(root);
    if (item) observer.observe(item);
    observed.current = { observer, host: root, item };
  });

  useEffect(
    () => () => {
      observed.current?.observer.disconnect();
      observed.current = null;
      stop();
    },
    [],
  );
}

/**
 * The indicator's markup: a middle and two ends, painted in that order, hidden from assistive technology. In a list,
 * render it `as="li"` so the list holds only items.
 */
export function EosIndicator({ ref, as = "span", className, style }: { ref?: Ref<HTMLElement>; as?: "span" | "li"; className?: string; style?: CSSProperties }) {
  return createElement(
    as,
    { ref, className: cx("eos-ind", className), style, "aria-hidden": true },
    createElement("span", { className: "eos-ind-m" }),
    createElement("span", { className: "eos-ind-l" }),
    createElement("span", { className: "eos-ind-r" }),
  );
}

/* ------------------------------------------------------------------------------------------------------------------ */
/* Lists: rise in, move with FLIP, fade out                                                                            */
/* ------------------------------------------------------------------------------------------------------------------ */

export interface EosListMotionOptions {
  /** The positioned container of the items; each item carries data-eos-key. */
  list: RefObject<HTMLElement | null>;
  /** An empty element inside the container (EosGhosts) where leaving items fade out. */
  ghosts: RefObject<HTMLElement | null>;
  /** The keys of the items shown, in order. */
  keys: readonly string[];
  /** How many places into the page's rise the first item starts, on load. */
  offset?: number;
  look?: EosLook;
}

interface ListState {
  keys: readonly string[];
  boxes: Map<string, EosBox>;
  nodes: Map<string, HTMLElement>;
  delays: Map<string, number>;
}

interface ListMove {
  dx: number;
  dy: number;
  duration: number;
  animation: Animation;
}

const itemsOf = (list: HTMLElement) => {
  const nodes = new Map<string, HTMLElement>();
  for (const child of list.children) {
    const key = child instanceof HTMLElement ? child.dataset.eosKey : undefined;
    if (key !== undefined) nodes.set(key, child as HTMLElement);
  }
  return nodes;
};

const layoutBox = (node: HTMLElement): EosBox => ({ x: node.offsetLeft, y: node.offsetTop, w: node.offsetWidth, h: node.offsetHeight });

/**
 * Motion for a list whose items change. Items that arrive rise in (on load in the page's stagger, later in a stagger of
 * their own); items that stay move to their new place with FLIP, from wherever they show if they are still moving; and
 * items that leave fade out quickly where they were, as inert copies, so the list itself changes at once. Returns each
 * item's style for its rise; each item also needs the eos-rise class and data-eos-key.
 */
export function useEosListMotion({ list, ghosts, keys, offset = 0, look }: EosListMotionOptions): (key: string) => CSSProperties {
  const committed = useRef<ListState | null>(null);
  const moving = useRef(new Map<string, ListMove>());
  const prior = committed.current;
  const motion = eosMotion(look);
  const fresh = prior ? keys.filter((key) => !prior.keys.includes(key)) : [...keys];
  const delayOf = (key: string) => prior?.delays.get(key) ?? eosStagger((prior ? 0 : offset) + fresh.indexOf(key), motion);

  useIsoLayoutEffect(() => {
    const root = list.current;
    if (!root) return;
    const before = committed.current;
    const nodes = itemsOf(root);
    const boxes = new Map<string, EosBox>();
    for (const [key, node] of nodes) boxes.set(key, layoutBox(node));
    const changed = before !== null && (before.keys.length !== keys.length || before.keys.some((key, i) => key !== keys[i]));
    const timing = (duration: number): KeyframeAnimationOptions => ({ duration, easing: eosEaseCss(motion.ease) });
    if (before && changed && eosCanAnimate(root)) {
      const ease = eosBezier(motion.ease);
      for (const [key, node] of nodes) {
        const was = before.boxes.get(key);
        const now = boxes.get(key);
        if (!was || !now || !before.nodes.has(key)) continue;
        // Still on its way from the last change: start from where it shows.
        const last = moving.current.get(key);
        let carry = { x: 0, y: 0 };
        if (last) {
          const time = last.animation.currentTime;
          const left = typeof time === "number" && time < last.duration ? 1 - ease(time / last.duration) : 0;
          carry = { x: last.dx * left, y: last.dy * left };
          last.animation.cancel();
          moving.current.delete(key);
        }
        const dx = was.x + carry.x - now.x;
        const dy = was.y + carry.y - now.y;
        if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5) continue;
        const animation = node.animate([{ transform: `translate(${dx}px, ${dy}px)` }, { transform: "translate(0px, 0px)" }], timing(motion.indicator));
        moving.current.set(key, { dx, dy, duration: motion.indicator, animation });
        // A card on its way passes over the ones rising in, not under them.
        node.style.zIndex = "1";
        const done = () => {
          if (moving.current.get(key)?.animation !== animation) return;
          moving.current.delete(key);
          node.style.zIndex = "";
        };
        animation.finished.then(done, done);
      }
    }
    // Leaving items fade where they were. Under reduced motion they go at once: what follows the list then lands
    // without sliding, and a fading copy would show over it.
    if (before && changed && eosCanAnimate(root)) {
      const leave = motion.leave;
      const layer = ghosts.current;
      for (const key of before.keys) {
        if (nodes.has(key) || !layer) continue;
        const gone = before.nodes.get(key);
        const box = before.boxes.get(key);
        if (!gone || !box) continue;
        const ghost = gone.cloneNode(true) as HTMLElement;
        ghost.classList.add("eos-ghost");
        ghost.classList.remove("eos-rise");
        ghost.removeAttribute("data-eos-key");
        ghost.removeAttribute("id");
        ghost.setAttribute("inert", "");
        Object.assign(ghost.style, { position: "absolute", left: `${box.x}px`, top: `${box.y}px`, width: `${box.w}px`, height: `${box.h}px`, margin: "0" });
        layer.appendChild(ghost);
        const fade = ghost.animate([{ opacity: 1 }, { opacity: 0 }], { ...timing(leave), fill: "forwards" });
        const remove = () => ghost.remove();
        fade.finished.then(remove, remove);
        setTimeout(remove, leave + 400);
      }
    }
    const delays = new Map<string, number>();
    for (const key of keys) delays.set(key, delayOf(key));
    committed.current = { keys: [...keys], boxes, nodes, delays };
  });

  // A resize moves items without a change of keys: remember where they are now.
  useEffect(() => {
    const root = list.current;
    if (!root || typeof ResizeObserver !== "function") return;
    const observer = new ResizeObserver(() => {
      const state = committed.current;
      if (!state) return;
      for (const [key, node] of itemsOf(root)) state.boxes.set(key, layoutBox(node));
    });
    observer.observe(root);
    return () => observer.disconnect();
  }, [list]);

  return (key: string) => ({ "--eos-rise-delay": `${delayOf(key)}ms` }) as CSSProperties;
}

/**
 * What comes after a list that changes height slides to its new place on transform instead of jumping. Call the
 * returned `mark()` in the event that changes the list, before the change renders; when `change` has rendered, each
 * element `after()` gave slides from where it showed, with the indicator's timing. Only what shows moves, a second
 * change starts from where things are on screen, and without motion they simply land.
 */
export function useEosFollow(after: () => readonly HTMLElement[], change: unknown, look?: EosLook): () => void {
  const marks = useRef<Map<HTMLElement, number> | null>(null);
  const running = useRef(new Map<HTMLElement, Animation>());
  const latest = useRef(after);
  latest.current = after;
  useIsoLayoutEffect(() => {
    const before = marks.current;
    marks.current = null;
    if (!before) return;
    const motion = eosMotion(look);
    const height = typeof window === "undefined" ? 0 : window.innerHeight;
    for (const [node, was] of before) {
      running.current.get(node)?.cancel();
      running.current.delete(node);
      if (!node.isConnected || !eosCanAnimate(node)) continue;
      const now = node.getBoundingClientRect().top;
      const dy = was - now;
      if (Math.abs(dy) < 1 || (Math.min(was, now) > height && height > 0)) continue;
      const animation = node.animate([{ transform: `translateY(${dy}px)` }, { transform: "translateY(0px)" }], {
        duration: motion.indicator,
        easing: eosEaseCss(motion.ease),
      });
      running.current.set(node, animation);
      const done = () => {
        if (running.current.get(node) === animation) running.current.delete(node);
      };
      animation.finished.then(done, done);
    }
  }, [change]);
  return () => {
    const next = new Map<HTMLElement, number>();
    for (const node of latest.current()) next.set(node, node.getBoundingClientRect().top);
    marks.current = next;
  };
}

/** The empty layer where a list's leaving items fade out. Nothing in it is reachable or announced. */
export function EosGhosts({ ref }: { ref?: Ref<HTMLDivElement> }) {
  return createElement("div", { ref, className: "eos-ghosts", "aria-hidden": true });
}
